from __future__ import annotations

import html
import json

from ..taxonomy import Vibe


def render_page(rows: list[dict] | None = None, vibe: str | None = None, query: str | None = None) -> str:
    initial = ""
    vibes = json.dumps([item.value for item in Vibe], ensure_ascii=False)
    return f"""<!doctype html>
<html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>
<title>VibeSorter Browser</title>
<style>
:root{{font-family:system-ui,sans-serif;color-scheme:dark;background:#0d0e12;color:#eee}}*{{box-sizing:border-box}}body{{margin:0;padding:28px;max-width:1500px;margin-inline:auto}}h1{{margin:0 0 6px}}p{{color:#aaa;margin:0}}.layout{{display:grid;grid-template-columns:270px 1fr;gap:24px;margin-top:24px}}.sidebar{{border:1px solid #292c35;border-radius:14px;padding:14px;height:max-content;position:sticky;top:20px}}.group{{border-top:1px solid #292c35;padding:12px 0}}.group:first-child{{border-top:0;padding-top:0}}.group h2{{font-size:12px;color:#aaa;text-transform:uppercase;margin:0 0 8px}}.choices{{display:flex;flex-wrap:wrap;gap:6px}}label.choice{{background:#181a21;border:1px solid #30333d;border-radius:8px;padding:7px 9px;font-size:12px;cursor:pointer}}label.choice:has(input:checked){{border-color:#6ea8fe;background:#202733}}input[type=checkbox]{{accent-color:#6ea8fe}}form{{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 14px}}input[type=text],select,button{{background:#181a21;color:#eee;border:1px solid #30333d;border-radius:10px;padding:10px 13px}}input[type=text]{{min-width:260px}}select{{cursor:pointer}}button{{cursor:pointer}}button:hover{{border-color:#555b69}}.grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px}}.card{{border:1px solid #292c35;border-radius:14px;overflow:hidden;background:#15171d;cursor:pointer}}.thumb{{display:block;width:100%;height:180px;object-fit:cover;background:#111218}}.thumb.broken{{display:grid;place-items:center;color:#777;border-bottom:1px solid #292c35;font-size:12px}}.meta{{padding:13px;display:grid;gap:5px}}.meta strong{{font-size:15px}}.meta span,.meta small{{font-size:12px;color:#aaa}}.toolbar{{display:flex;justify-content:space-between;margin:14px 0;color:#999;font-size:13px}}.empty{{padding:40px;border:1px dashed #393c46;border-radius:14px;color:#999}}.modal{{position:fixed;inset:0;background:#000b;display:grid;place-items:center;padding:24px;z-index:10}}.modal[hidden]{{display:none}}.dialog{{width:min(1000px,100%);max-height:90vh;overflow:auto;background:#15171d;border:1px solid #30333d;border-radius:18px;padding:20px;position:relative}}.close{{position:absolute;right:16px;top:16px}}.detail{{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:28px}}.detail-image{{width:100%;max-height:65vh;object-fit:contain}}.profile{{display:grid;gap:8px}}.profile div{{display:flex;justify-content:space-between;border-top:1px solid #292c35;padding:8px 0;font-size:13px}}.feedback{{border:1px solid #343946;border-radius:12px;padding:14px;margin:18px 0;display:grid;gap:9px}}.feedback p{{font-size:12px;color:#aaa}}.feedback-actions{{display:flex;flex-wrap:wrap;gap:8px}}.feedback-actions button{{font-size:12px}}@media(max-width:850px){{.layout{{grid-template-columns:1fr}}.sidebar{{position:static}}.detail{{grid-template-columns:1fr}}}}
</style></head>
<body><h1>VibeSorter</h1><p>Local browser · cached analysis only · multidimensional filters <button id='preferences'>Personal preferences</button></p>
<div id='db-status' role='status' aria-live='polite' style='margin-top:14px;padding:12px 14px;border:1px solid #30333d;border-radius:8px;color:#bbb'>Checking local analysis database…</div>
<section id='preferences-panel' class='feedback' hidden><h2>Personal preferences</h2><p>These corrections are stored in this library's SQLite database only.</p><p id='preference-adjustments'></p><ul id='correction-list'></ul><div class='feedback-actions'><button id='clear-preferences'>Clear all corrections</button><button id='close-preferences'>Close</button></div></section><div class='layout'><aside class='sidebar'><div id='filters'>Loading filters…</div></aside><main>
<form id='search'><label>Sort <select id='sort'><option value='path'>Name</option><option value='modified'>Modified</option><option value='size'>Size</option><option value='confidence'>Confidence</option></select></label><input id='query' type='text' placeholder='Search paths...' value='{html.escape(query or '', quote=True)}'><button type='submit'>Apply filters</button><button id='clear' type='button'>Clear all</button></form><div id='active' class='toolbar' aria-live='polite'></div>
<div class='toolbar'><span id='summary'>Loading…</span><button id='more' type='button' hidden>Load more</button></div><section id='grid' class='grid'>{initial}</section><div id='empty' class='empty' hidden>No cached analysis matched these filters.<br><button id='retry' type='button' hidden>Retry</button></div></main></div>
<div id='modal' class='modal' hidden role='dialog' aria-modal='true' aria-labelledby='detail-title'><section class='dialog' tabindex='-1'><button id='close' class='close' aria-label='Close image details'>Close</button><div id='detail'></div></section></div>
<script>
const allVibes=${vibes};const families=['media_type','colors','temperature','saturation','brightness','vibes'];const labels={{media_type:'Media type',colors:'Color',temperature:'Temperature',saturation:'Saturation',brightness:'Brightness',vibes:'Vibes'}};let page=1,total=0,limit=48;let visiblePaths=[];let currentPath=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
function renderFilters(values){{document.getElementById('filters').innerHTML=families.map(f=>`<section class='group'><h2>${{labels[f]}}</h2><div class='choices'>${{(values[f]||[]).map(v=>`<label class='choice'><input type='checkbox' name='${{f}}' value='${{esc(v)}}'> ${{esc(v)}}</label>`).join('')}}</div></section>`).join('');}}
function updateActive(){{const checked=document.querySelectorAll('input[type=checkbox]:checked').length;const query=document.getElementById('query').value.trim();const parts=[];if(query)parts.push('Search: '+query);if(checked)parts.push(checked+' filter'+(checked===1?'':'s')+' active');document.getElementById('active').textContent=parts.join(' · ')||'No filters active';}}
function selectedParams(){{const p=new URLSearchParams();p.set('q',document.getElementById('query').value);p.set('sort',document.getElementById('sort').value);families.forEach(f=>document.querySelectorAll(`input[name='${{f}}']:checked`).forEach(i=>p.append(f,i.value)));p.set('page',page);p.set('limit',limit);return p;}}
function card(row){{const path=String(row.path||'');const label=String(row.vibe||'Needs review');const confidence=Number(row.confidence);const category=String(row.confidence_category||'unknown');const personal=row.personalized&&row.personalized_vibe?' · personal preference: '+row.personalized_vibe:'';const profile=row.profile||{{}};const tags=[profile.media_type?.value,...(profile.colors||[]).map(x=>x.value),profile.temperature?.value,profile.saturation?.value,profile.brightness?.value,...(profile.vibes||[]).map(x=>x.value)].filter(Boolean);return `<article class='card' tabindex='0' data-path='${{esc(path)}}'><img class='thumb' src='/api/thumbnail?path=${{encodeURIComponent(path)}}' alt='${{esc(label)}}' loading='lazy' onerror="this.outerHTML='<div class=\'thumb broken\'>Image unavailable</div>'"><div class='meta'><strong>${{esc(label)}}</strong><span>${{Number.isFinite(confidence)?category+' · '+Math.round(confidence*100)+'% heuristic ranking signal':''}}${{esc(personal)}}${{tags.length?' · '+esc(tags.join(' · ')):''}}</span><small title='Full image path'>${{esc(path)}}</small></div></article>`;}}
function bind(){{document.querySelectorAll('.card').forEach(c=>{{c.onclick=()=>openDetail(c.dataset.path);c.onkeydown=e=>{{if(e.key==='Enter')openDetail(c.dataset.path)}}}})}}
async function load(reset=true){{if(reset){{page=1;grid.innerHTML='';summary.textContent='Loading…';empty.hidden=true;empty.innerHTML="No cached analysis matched these filters.<br><button id='retry' type='button' hidden>Retry</button>"}}try{{const data=await fetchJson('/api/images?'+selectedParams());total=data.total;if(reset)visiblePaths=[];data.items.forEach(x=>{{visiblePaths.push(String(x.path||''));grid.insertAdjacentHTML('beforeend',card(x));}});bind();summary.textContent=total?`Showing ${{Math.min(page*limit,total)}} of ${{total}} images`:'No results';updateActive();empty.hidden=total!==0;more.hidden=page*limit>=total}}catch(error){{summary.textContent='Could not load images';empty.hidden=false;empty.innerHTML=esc(error.message)+'<br><button id="retry" type="button">Retry</button>';more.hidden=true;document.getElementById('retry').onclick=()=>load()}}}}
async function openDetail(path){{currentPath=path;modal.hidden=false;detail.textContent='Loading…';try{{const d=await fetchJson('/api/image-details?path='+encodeURIComponent(path));const p=d.profile||{{}};const confidenceText=d.confidence_category?`${{d.confidence_category}} · ${{Math.round(Number(d.confidence||0)*100)}}% heuristic ranking signal (not probability)`:'—';const values=[['Suggested label',d.vibe||'None — needs review'],['Top-ranked raw score',d.top_ranked||'—'],['Evidence category',d.confidence_category||'unknown'],['Reason',d.reason||'No explanation available'],['Margin',Number.isFinite(Number(d.margin))?Number(d.margin).toFixed(3):'—'],['Media type',p.media_type?.value],['Colors',(p.colors||[]).map(x=>x.value).join(', ')],['Temperature',p.temperature?.value],['Saturation',p.saturation?.value],['Brightness',p.brightness?.value],['Vibes',(p.vibes||[]).map(x=>x.value).join(', ')],['Personalized ranking',d.personalized_vibe?d.personalized_vibe+' (local preference)':'No personal adjustment']];const correction=d.correction?`Saved locally: ${{d.correction.verdict}} · ${{d.correction.suggested_label}}`:'No correction saved for this image';detail.innerHTML=`<div class='detail'><img class='detail-image' src='/api/image?path=${{encodeURIComponent(d.path)}}' alt='${{esc(d.vibe||'Image detail')}}'><div><h2>${{esc(d.vibe||'Needs review')}}</h2><p>${{esc(confidenceText)}}</p><div class='profile'>${{values.map(([k,v])=>`<div><span>${{esc(k)}}</span><strong>${{esc(v||'—')}}</strong></div>`).join('')}}</div><section class='feedback'><h3>Personal correction</h3><p>Stored only in this local SQLite database. It never changes raw classifier scores or uploads your image.</p><p>${{esc(correction)}}</p><label>Corrected vibe (for partially correct): <select id='corrected-label'>${{allVibes.map(v=>`<option value='${{esc(v)}}'>${{esc(v)}}</option>`).join('')}}</select></label><div class='feedback-actions'><button data-verdict='correct'>Mark correct</button><button data-verdict='incorrect'>Mark incorrect</button><button data-verdict='partial'>Partially correct</button></div><div class='feedback-actions'><button id='undo-correction'>Undo latest correction</button><button id='clear-corrections'>Clear all corrections</button></div><p id='feedback-status' role='status'></p></section></div></div>`;detail.querySelectorAll('[data-verdict]').forEach(button=>button.onclick=()=>saveCorrection(d,button.dataset.verdict));document.getElementById('undo-correction').onclick=undoCorrection;document.getElementById('clear-corrections').onclick=clearCorrections;}}catch(error){{detail.innerHTML='<p class=\\'empty\\'>Could not load this image: '+esc(error.message)+'</p>'}}}}
async function correctionPost(url,payload={{}}){{const response=await fetch(url,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(payload)}});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${{response.status}}`);return data;}}
async function saveCorrection(detailData,verdict){{const status=document.getElementById('feedback-status');try{{const corrected=document.getElementById('corrected-label').value;await correctionPost('/api/corrections',{{path:detailData.path,suggested_label:detailData.top_ranked,verdict,corrected_label:verdict==='partial'?corrected:null}});status.textContent='Saved locally. Personalized ranking updated.';await openDetail(detailData.path);}}catch(error){{status.textContent=error.message;}}}}
async function undoCorrection(){{const status=document.getElementById('feedback-status');try{{const data=await correctionPost('/api/corrections/undo');status.textContent=data.undone?'Latest correction undone.':'No correction to undo.';if(currentPath)await openDetail(currentPath);}}catch(error){{status.textContent=error.message;}}}}
async function clearCorrections(){{if(!confirm('Clear all locally stored personal corrections and preferences?'))return;const status=document.getElementById('feedback-status');try{{const data=await correctionPost('/api/corrections/clear');status.textContent=`Cleared ${{data.cleared}} correction(s).`;if(currentPath)await openDetail(currentPath);}}catch(error){{status.textContent=error.message;}}}}
async function showPreferences(){{const panel=document.getElementById('preferences-panel');panel.hidden=false;try{{const data=await fetchJson('/api/preferences');const entries=data.corrections||[];document.getElementById('preference-adjustments').textContent=Object.entries(data.adjustments||{{}}).map(([name,value])=>name+': '+(value>0?'+':'')+value.toFixed(3)).join(' · ')||'No active personal ranking adjustments';document.getElementById('correction-list').innerHTML=entries.map(item=>'<li>'+esc(item.verdict)+' · '+esc(item.suggested_label)+(item.corrected_label?' → '+esc(item.corrected_label):'')+'<br><small>'+esc(item.path)+'</small></li>').join('')||'<li>No corrections stored.</li>';}}catch(error){{document.getElementById('preference-adjustments').textContent=error.message;}}}}
async function clearPreferences(){{if(!confirm('Clear every local correction and personal preference?'))return;try{{const data=await correctionPost('/api/corrections/clear');document.getElementById('preference-adjustments').textContent='Cleared '+data.cleared+' correction(s).';document.getElementById('correction-list').innerHTML='';if(currentPath)await openDetail(currentPath);}}catch(error){{document.getElementById('preference-adjustments').textContent=error.message;}}}}document.getElementById('preferences').onclick=showPreferences;document.getElementById('close-preferences').onclick=()=>document.getElementById('preferences-panel').hidden=true;document.getElementById('clear-preferences').onclick=clearPreferences;document.getElementById('search').onsubmit=e=>{{e.preventDefault();load()}};document.getElementById('clear').onclick=()=>{{document.getElementById('query').value='';document.querySelectorAll('input[type=checkbox]').forEach(i=>i.checked=false);load()}};document.getElementById('more').onclick=()=>{{page++;load(false)}};document.getElementById('filters').addEventListener('change',load);document.getElementById('close').onclick=()=>{{modal.hidden=true;currentPath=null}};modal.onclick=e=>{{if(e.target===modal){{modal.hidden=true;currentPath=null}}}};document.addEventListener('keydown',e=>{{if(modal.hidden)return;if(e.key==='Escape'){{modal.hidden=true;currentPath=null;return}}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){{const index=visiblePaths.indexOf(currentPath);if(index<0)return;const next=e.key==='ArrowLeft'?index-1:index+1;if(next>=0&&next<visiblePaths.length)openDetail(visiblePaths[next]);}}}});
fetch('/api/status').then(r=>r.ok?r.json():Promise.reject(new Error('Could not inspect the local database'))).then(s=>{{const el=document.getElementById('db-status');el.textContent=s.message;el.dataset.state=s.state;if(s.state==='missing'||s.state==='incompatible'||s.state==='unreadable'){{el.style.borderColor='#8a5360';el.style.color='#ffb9c4'}}else if(s.state==='empty'){{el.style.borderColor='#776b43';el.style.color='#e8d59b'}}else{{el.style.borderColor='#3c6553';el.style.color='#b7e6cc'}}}}).catch(error=>{{document.getElementById('db-status').textContent=error.message}});fetch('/api/attributes').then(r=>r.ok?r.json():Promise.reject(new Error('Could not load filters'))).then(d=>renderFilters(d.values)).catch(error=>{{document.getElementById('filters').textContent=error.message}});load();
</script></body></html>"""